"""Deep, vertical-specific website blueprints.

Each vertical gets its own voice, IA, service taxonomy, catalogue semantics and
visual layout family. The public site engine consumes this file; no sales/admin
copy lives here.
"""

P = "https://images.pexels.com/photos/{}/pexels-photo-{}.jpeg?auto=compress&cs=tinysrgb&w=1600&h=1100&fit=crop"
def img(n): return P.format(n,n)

def svc(name, desc, meta=""): return {"name":name,"desc":desc,"meta":meta}
def item(title, subtitle, image, badge=""): return {"title":title,"subtitle":subtitle,"image":img(image),"badge":badge}

